SINA_SMART["bacterio1-antibiotics"] = {"lecture":"bacterio1-antibiotics","title":"Antibiotics","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"bacterio1-antibiotics:e0","text":"Antibiotic: selective toxicity, low mg/L; antiseptic: non-selective, local, high %.","topic":"Antibiotics and antiseptics","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-antibiotics:e1","text":"β-lactams bind PBPs: bactericidal.","topic":"β-lactams","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-antibiotics:e2","text":"Penicillin M: penicillinase-producing S. aureus, not MRSA (altered PBP).","topic":"β-lactams","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-antibiotics:e3","text":"Amoxicillin + clavulanic acid: inhibitor protects the β-lactam.","topic":"β-lactams","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-antibiotics:e4","text":"3rd-gen cephalosporins: Gram-negatives; inactive on enterococci and Listeria; ESBL-sensitive.","topic":"β-lactams","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-antibiotics:e5","text":"Carbapenems: widest; stable to ESBL; reserve drugs.","topic":"β-lactams","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-antibiotics:e6","text":"Vancomycin: Gram-positives only; colistin: Gram-negatives, nephrotoxic.","topic":"Other cell wall and membrane agents","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-antibiotics:e7","text":"30S: aminoglycosides, tetracyclines; 50S: macrolides, clindamycin, chloramphenicol.","topic":"Protein and nucleic acid synthesis inhibitors","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-antibiotics:e8","text":"Aminoglycosides: nephro- and ototoxic; chloramphenicol: marrow aplasia.","topic":"Protein and nucleic acid synthesis inhibitors","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-antibiotics:e9","text":"Fluoroquinolones: gyrase/topo IV; rifampicin: RNA polymerase, never alone.","topic":"Protein and nucleic acid synthesis inhibitors","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-antibiotics:e10","text":"Synergy: ampicillin + gentamicin; antagonism: static + β-lactam.","topic":"Combinations and resistance","sec":4,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"pzilou":"a","ad5xuh":"a","16e27cj":"a","1r6lolb":"a","3kdsud":"a","19qwa20":"a","mxq62k":"a","1lisr4q":"a","11znslw":"a","nmoe10":"a","15cbcl6":"a","14mcxi7":"a","3xmkav":"a","1u64rjk":"a","1poimlb":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"bacterio1-antibiotics:e0":{"s":0,"u":["Antibiotic: selective toxicity, low mg/L; antiseptic: non-selective, local, high %.","An antibiotic kills or inhibits bacteria without harming the host ( selective toxicity ); it is natural (fungi, bacteria: Penicillium notatum makes penicillin G) or synthetic, acts over hours, diffuses into tissues and is active at very low concentrations (mg/L) .","Antiseptics and disinfectants (alcohols, iodine, chlorhexidine) act in minutes, non-selectively, only locally and at high concentrations (%)."],"dp":[]},"bacterio1-antibiotics:e1":{"s":1,"u":["β-lactams bind PBPs: bactericidal.","All bind penicillin-binding proteins and block peptidoglycan synthesis: bactericidal ."],"dp":[]},"bacterio1-antibiotics:e2":{"s":1,"u":["Penicillin M: penicillinase-producing S. aureus, not MRSA (altered PBP).","Penicillin M (methicillin, oxacillin, cloxacillin): penicillinase-producing S. aureus , but not MRSA , whose altered PBP has low affinity.","Penicillin G/V : streptococci, Neisseria , Listeria , Treponema pallidum , most anaerobes; not staphylococci making penicillinase, not Gram-negative bacilli (outer membrane)."],"dp":[]},"bacterio1-antibiotics:e3":{"s":1,"u":["Amoxicillin + clavulanic acid: inhibitor protects the β-lactam.","Carboxy- and ureidopenicillins (ticarcillin, piperacillin) cover Pseudomonas . β-lactamase inhibitors (clavulanic acid, sulbactam, tazobactam, avibactam) have no antibacterial activity themselves; they are 'suicide inhibitors' protecting the partner β-lactam."],"dp":[{"h":"Why amoxicillin works in otitis but fails in some urinary infections","t":"Amoxicillin kills E. coli only if the strain lacks a β-lactamase. Many community E. coli now carry one, so amoxicillin alone fails in a large share of urinary infections, while adding clavulanic acid (a suicide inhibitor) restores activity against the common enzymes. ESBL-producing strains, however, also destroy third-generation cephalosporins, and carbapenemase producers destroy almost everything. The choice of drug therefore follows the local resistance pattern and the culture result, which is why urine cultures matter when a first treatment fails. Source: the lecture's penicillin A spectrum, β-lactamase inhibitors and ESBLs."}]},"bacterio1-antibiotics:e4":{"s":1,"u":["3rd-gen cephalosporins: Gram-negatives; inactive on enterococci and Listeria; ESBL-sensitive.","Cephalosporins : 1st generation (cefazolin) Gram-positives; 2nd (cefuroxime, cefoxitin) more Gram-negatives and some anaerobes; 3rd (cefotaxime, ceftriaxone , ceftazidime) very active on Gram-negative bacilli, diffusible, but inactive on enterococci and Listeria and destroyed by ESBLs ; 4th (cefepime) adds Pseudomonas , Enterobacter ; 5th ( ceftaroline ) active against MRSA .","Penicillin G/V : streptococci, Neisseria , Listeria , Treponema pallidum , most anaerobes; not staphylococci making penicillinase, not Gram-negative bacilli (outer membrane)."],"dp":[]},"bacterio1-antibiotics:e5":{"s":1,"u":["Carbapenems: widest; stable to ESBL; reserve drugs.","Carbapenems (imipenem, meropenem, ertapenem): widest spectrum, stable to most β-lactamases including ESBLs; reserved for severe or multiresistant hospital infections."],"dp":[]},"bacterio1-antibiotics:e6":{"s":2,"u":["Vancomycin: Gram-positives only; colistin: Gram-negatives, nephrotoxic.","Polymyxins (polymyxin B, colistin ): cationic peptides disrupting Gram-negative membranes; natural resistance in Proteus , Serratia , Providencia ; poor tissue diffusion and nephrotoxic , so kept for multiresistant Gram-negatives.","Glycopeptides (vancomycin, teicoplanin): bactericidal, Gram-positives only , including methicillin-resistant staphylococci."],"dp":[]},"bacterio1-antibiotics:e7":{"s":3,"u":["30S: aminoglycosides, tetracyclines; 50S: macrolides, clindamycin, chloramphenicol.","Macrolides, lincosamides and streptogramins (erythromycin, azithromycin, clarithromycin, clindamycin, pristinamycin): 50S , bacteriostatic; Gram-positives and intracellular or atypical bacteria ( Chlamydia , Mycoplasma , Legionella , Campylobacter ).","Note: one slide places chloramphenicol on the 30S subunit; it binds the 50S subunit, as the lecture's summary table states."],"dp":[]},"bacterio1-antibiotics:e8":{"s":3,"u":["Aminoglycosides: nephro- and ototoxic; chloramphenicol: marrow aplasia.","Chloramphenicol : 50S , broad spectrum, excellent diffusion, but bone marrow aplasia ; topical eye use, sometimes typhoid or meningitis.","Aminoglycosides (gentamicin, amikacin, tobramycin, streptomycin): bind 30S , cause misreading, bactericidal ; given parenterally; active on aerobic Gram-negative bacilli, staphylococci and mycobacteria; inactive alone on streptococci and anaerobes; nephrotoxic and ototoxic ."],"dp":[]},"bacterio1-antibiotics:e9":{"s":3,"u":["Fluoroquinolones: gyrase/topo IV; rifampicin: RNA polymerase, never alone.","Rifampicin inhibits RNA polymerase ; key anti-tuberculosis drug, never used alone (selects resistant mutants)."],"dp":[]},"bacterio1-antibiotics:e10":{"s":4,"u":["Synergy: ampicillin + gentamicin; antagonism: static + β-lactam.","Synergy : ampicillin + gentamicin (enterococcal endocarditis), vancomycin + gentamicin (serious MRSA), trimethoprim + sulfamethoxazole, piperacillin-tazobactam + aminoglycoside ( Pseudomonas ).","Antagonism : a bacteriostatic drug with a bactericidal β-lactam (penicillin + tetracycline or chloramphenicol in pneumococcal infection), because β-lactams need growing bacteria."],"dp":[]}},"meta":{"pzilou":{"a":"recall","vg":"bacterio1-antibiotics:e0/recall/1"},"ad5xuh":{"a":"recall","vg":"bacterio1-antibiotics:e1/recall/1"},"16e27cj":{"a":"recall","vg":"bacterio1-antibiotics:e2/recall/1"},"1r6lolb":{"a":"recall","vg":"bacterio1-antibiotics:e3/recall/1"},"3kdsud":{"a":"recall","vg":"bacterio1-antibiotics:e4/recall/1"},"19qwa20":{"a":"recall","vg":"bacterio1-antibiotics:e5/recall/1"},"mxq62k":{"a":"recall","vg":"bacterio1-antibiotics:e6/recall/1"},"1lisr4q":{"a":"recall","vg":"bacterio1-antibiotics:e7/recall/1"},"11znslw":{"a":"recall","vg":"bacterio1-antibiotics:e8/recall/1"},"nmoe10":{"a":"recall","vg":"bacterio1-antibiotics:e7/recall/2"},"15cbcl6":{"a":"recall","vg":"bacterio1-antibiotics:e7/recall/3"},"14mcxi7":{"a":"recall","vg":"bacterio1-antibiotics:e8/recall/2"},"3xmkav":{"a":"recall","vg":"bacterio1-antibiotics:e9/recall/1"},"1u64rjk":{"a":"recall","vg":"bacterio1-antibiotics:e9/recall/2"},"1poimlb":{"a":"recall","vg":"bacterio1-antibiotics:e10/recall/1"}},"explRev":"7c28fa9ce7c8"};
